//! 📊️ Original Source progress retains the exact typed span and checkpoint actions.
use super::{OriginalCheckpointRequest,OriginalRecordedAction,OriginalRecordedIdentity,OriginalSpanRequest,SendOriginalRecordedLoan};
use crate::{NativeAllocationIdentity,NativeAllocationLedger,OriginalSourceTurnIdentity,OriginalSourceTurnWitness,ValueError,ValueRefusalKind};
#[derive(Clone,Copy,PartialEq,Eq)]
enum Phase{Start,Span,End}
enum Reply{Span(Result<(),ValueError>),Checkpoint(Result<bool,ValueError>)}
/// 🧳️ Owns the original Source, ledger, progress and every unfinished producer reply.
pub struct OriginalSourceProgressState{source:OriginalSourceTurnIdentity,ledger:NativeAllocationIdentity,identity:NativeAllocationIdentity,span:OriginalRecordedIdentity,checkpoint:OriginalRecordedIdentity,stage:u64,prior:usize,next:usize,total:usize,owned:usize,phase:Phase,span_action:Option<OriginalRecordedAction<OriginalSpanRequest,()>>,checkpoint_action:Option<OriginalRecordedAction<OriginalCheckpointRequest,bool>>,reply:Option<Reply>,finished:bool}
impl OriginalSourceProgressState{
 /// 🔗️ Verifies both actual producer loans and their outstanding action identities.
 pub fn matches(&self,source:OriginalSourceTurnIdentity,ledger:&NativeAllocationLedger,span:&dyn SendOriginalRecordedLoan<OriginalSpanRequest,()>,checkpoint:&dyn SendOriginalRecordedLoan<OriginalCheckpointRequest,bool>)->bool{self.source==source&&self.ledger==ledger.identity()&&ledger.matches_progress(self.identity)&&self.span==span.identity()&&self.checkpoint==checkpoint.identity()&&self.span_action.as_ref().map_or_else(||!span.has_pending_action(),|action|span.matches_action(Some(action)))&&self.checkpoint_action.as_ref().map_or_else(||!checkpoint.has_pending_action(),|action|checkpoint.matches_action(Some(action)))}
 /// 📏️ Verifies the actual original progress snapshot without transferring custody.
 pub fn matches_progress(&self,stage:u64,completed:usize,total:usize,owned:usize,started:bool)->bool{self.stage==stage&&self.total==total&&self.owned==owned&&started==(self.phase!=Phase::Start)&&completed==if self.phase==Phase::End{self.next}else{self.prior}}
}
impl Drop for OriginalSourceProgressState{fn drop(&mut self){assert!(std::thread::panicking()||self.finished,"original Source progress requires settlement")}}
impl crate::retirement::RetireOwned for OriginalSourceProgressState{
 type RetirementCursor=crate::NativeRetirementGate<Self,<() as crate::retirement::RetireOwned>::RetirementCursor>;
 fn retirement_ready(&self)->bool{false}
 fn retirement_seed(self)->Self::RetirementCursor{crate::NativeRetirementGate::Pending(self)}
 fn retirement_birth_bytes(&self)->Option<usize>{None}
 fn controlled_retirement_supported()->bool{true}
}
/// 🔗️ Validates the actual Source producers, ledger and any resident progress action.
pub fn validate_source_progress(source:OriginalSourceTurnWitness<'_>,ledger:&NativeAllocationLedger,stage:u64,completed:usize,total:usize,started:bool,span:&mut dyn SendOriginalRecordedLoan<OriginalSpanRequest,()>,checkpoint:&mut dyn SendOriginalRecordedLoan<OriginalCheckpointRequest,bool>,state:Option<&OriginalSourceProgressState>)->Result<(),ValueError>{let invalid=||ValueError::literal(ValueRefusalKind::InvariantViolated,"Source progress changed its original authority or state");let turn=source.identity();if ledger.is_bound()||span.source_turn()!=Some(turn)||checkpoint.source_turn()!=Some(turn){return Err(invalid())}span.validate_context()?;checkpoint.validate_context()?;if state.map_or_else(||ledger.has_progress()||span.has_pending_action()||checkpoint.has_pending_action(),|state|!state.matches(turn,ledger,span,checkpoint)||!state.matches_progress(stage,completed,total,ledger.owned_bytes(),started)){return Err(invalid())}Ok(())}
/// 🤝️ Validates the same actual Source allocation, work and construction loans.
pub fn validate_source_authorities(source:OriginalSourceTurnWitness<'_>,allocation:&mut dyn crate::NativeSendAllocationLoan,work:&crate::OriginalWorkLoan<'_>,construction:&crate::OriginalConstructionLoan<'_>)->Result<(),ValueError>{let turn=source.identity();if allocation.source_turn()!=Some(turn)||work.source_turn()!=Some(turn)||construction.source_turn()!=Some(turn){return Err(crate::invariant())}allocation.validate_context()?;work.validate_context()?;construction.validate_context()}
/// 🧭️ Starts a stage only while the actual ledger and both producers are unoccupied.
pub fn begin_source_progress(source:OriginalSourceTurnWitness<'_>,ledger:&NativeAllocationLedger,stage:&mut u64,completed:&mut usize,total:&mut usize,started:&mut bool,span:&mut dyn SendOriginalRecordedLoan<OriginalSpanRequest,()>,checkpoint:&mut dyn SendOriginalRecordedLoan<OriginalCheckpointRequest,bool>,slot:Option<&OriginalSourceProgressState>,next_total:usize)->Result<(),ValueError>{if slot.is_some(){return Err(crate::invariant())}validate_source_progress(source,ledger,*stage,*completed,*total,*started,span,checkpoint,None)?;*stage=stage.checked_add(1).ok_or_else(||ValueError::literal(ValueRefusalKind::WorkLimit,"native encoding stage overflow"))?;*completed=0;*total=next_total;*started=false;Ok(())}
/// 🧳️ Retains an original checkpoint and its exact Source and ledger snapshot.
pub struct OriginalSourceCheckpointState{source:OriginalSourceTurnIdentity,ledger:NativeAllocationIdentity,identity:NativeAllocationIdentity,checkpoint:OriginalRecordedIdentity,stage:u64,completed:usize,total:usize,owned:usize,started:bool,action:Option<OriginalRecordedAction<OriginalCheckpointRequest,bool>>,reply:Option<Result<bool,ValueError>>,finished:bool}
impl OriginalSourceCheckpointState{
 /// 🔗️ Checks the actual original checkpoint, ledger and unchanged progress snapshot.
 pub fn matches(&self,source:OriginalSourceTurnIdentity,ledger:&NativeAllocationLedger,stage:u64,completed:usize,total:usize,started:bool,checkpoint:&dyn SendOriginalRecordedLoan<OriginalCheckpointRequest,bool>)->bool{self.source==source&&self.ledger==ledger.identity()&&ledger.matches_progress(self.identity)&&self.checkpoint==checkpoint.identity()&&self.stage==stage&&self.completed==completed&&self.total==total&&self.owned==ledger.owned_bytes()&&self.started==started&&self.action.as_ref().map_or_else(||!checkpoint.has_pending_action(),|action|checkpoint.matches_action(Some(action)))}
}
/// 🔐️ Validates a detached checkpoint against the original Source and both progress ports.
pub fn validate_source_checkpoint(source:OriginalSourceTurnWitness<'_>,ledger:&NativeAllocationLedger,stage:u64,completed:usize,total:usize,started:bool,span:&mut dyn SendOriginalRecordedLoan<OriginalSpanRequest,()>,checkpoint:&mut dyn SendOriginalRecordedLoan<OriginalCheckpointRequest,bool>,state:&OriginalSourceCheckpointState)->Result<(),ValueError>{let turn=source.identity();if ledger.is_bound()||span.source_turn()!=Some(turn)||checkpoint.source_turn()!=Some(turn)||span.has_pending_action()||!state.matches(turn,ledger,stage,completed,total,started,checkpoint){return Err(crate::invariant())}span.validate_context()?;checkpoint.validate_context()}
impl Drop for OriginalSourceCheckpointState{fn drop(&mut self){assert!(std::thread::panicking()||self.finished,"original Source checkpoint requires settlement")}}
impl crate::retirement::RetireOwned for OriginalSourceCheckpointState{type RetirementCursor=crate::NativeRetirementGate<Self,<() as crate::retirement::RetireOwned>::RetirementCursor>;fn retirement_ready(&self)->bool{false}fn retirement_seed(self)->Self::RetirementCursor{crate::NativeRetirementGate::Pending(self)}fn retirement_birth_bytes(&self)->Option<usize>{None}fn controlled_retirement_supported()->bool{true}}
/// 📍️ Runs or recovers one actual checkpoint without inventing a span event.
pub fn source_checkpoint(source:OriginalSourceTurnWitness<'_>,ledger:&mut NativeAllocationLedger,stage:u64,completed:usize,total:usize,started:&mut bool,checkpoint:&mut dyn SendOriginalRecordedLoan<OriginalCheckpointRequest,bool>,slot:&mut Option<OriginalSourceCheckpointState>)->Result<Option<Result<bool,ValueError>>,ValueError>{
 let invalid=||ValueError::literal(ValueRefusalKind::InvariantViolated,"Source checkpoint changed its original authority or state");let turn=source.identity();if ledger.is_bound()||checkpoint.source_turn()!=Some(turn){return Err(invalid())}checkpoint.validate_context()?;let ledger_id=ledger.identity();let owned=ledger.owned_bytes();if slot.is_none(){if checkpoint.has_pending_action(){return Err(invalid())}let identity=ledger.begin_progress()?;*slot=Some(OriginalSourceCheckpointState{source:turn,ledger:ledger_id,identity,checkpoint:checkpoint.identity(),stage,completed,total,owned,started:*started,action:None,reply:None,finished:false})}let state=slot.as_mut().expect("original checkpoint state installed");if state.source!=turn||state.ledger!=ledger_id||!ledger.matches_progress(state.identity)||state.checkpoint!=checkpoint.identity()||state.stage!=stage||state.completed!=completed||state.total!=total||state.owned!=owned||state.started!=*started||state.action.as_ref().map_or_else(||checkpoint.has_pending_action(),|action|!checkpoint.matches_action(Some(action))){return Err(invalid())}if state.reply.is_none(){if state.action.is_none(){checkpoint.begin(OriginalCheckpointRequest{completed,total,owned_bytes:owned},&mut state.action)?}else{let action=state.action.as_mut().expect("original checkpoint action retained");if !action.is_settled()&&!checkpoint.recover(action)?{return Ok(None)}}let action=state.action.as_mut().expect("original checkpoint action retained");if !action.is_settled(){return Ok(None)}state.reply=Some(action.take_reply().ok_or_else(invalid)?)}if state.action.is_some(){checkpoint.finish(&mut state.action)?}ledger.finish_progress(state.identity)?;let result=state.reply.take().ok_or_else(invalid)?;if matches!(result,Ok(true)){*started=true}state.finished=true;drop(slot.take());Ok(Some(result))
}
/// 📍️ Advances the actual caller-owned progress through its two original producers.
pub fn advance_source_progress(source:OriginalSourceTurnWitness<'_>,ledger:&mut NativeAllocationLedger,stage:u64,completed:&mut usize,total:usize,started:&mut bool,span:&mut dyn SendOriginalRecordedLoan<OriginalSpanRequest,()>,checkpoint:&mut dyn SendOriginalRecordedLoan<OriginalCheckpointRequest,bool>,units:usize,slot:&mut Option<OriginalSourceProgressState>)->Result<Option<Result<bool,ValueError>>,ValueError>{
 let invalid=||ValueError::literal(ValueRefusalKind::InvariantViolated,"Source progress changed its original authority or state");let turn=source.identity();if ledger.is_bound()||span.source_turn()!=Some(turn)||checkpoint.source_turn()!=Some(turn){return Err(invalid())}span.validate_context()?;checkpoint.validate_context()?;let identity=ledger.identity();let owned=ledger.owned_bytes();
 if slot.is_none(){let prior=*completed;let next=prior.checked_add(units).ok_or_else(||ValueError::literal(ValueRefusalKind::WorkLimit,"native encoding work overflow"))?;if total!=0&&next>total{return Err(ValueError::literal(ValueRefusalKind::WorkLimit,"native encoding exceeds declared workload"))}let progress_identity=ledger.begin_progress()?;*slot=Some(OriginalSourceProgressState{source:turn,ledger:identity,identity:progress_identity,span:span.identity(),checkpoint:checkpoint.identity(),stage,prior,next,total,owned,phase:if *started{Phase::Span}else{Phase::Start},span_action:None,checkpoint_action:None,reply:None,finished:false})}
 let state=slot.as_mut().expect("original progress state installed");if !state.matches(turn,ledger,span,checkpoint)||!state.matches_progress(stage,*completed,total,owned,*started)||state.next.checked_sub(state.prior)!=Some(units){return Err(invalid())}
 loop{match state.phase{
  Phase::Start|Phase::End=>{let is_start=state.phase==Phase::Start;if state.reply.is_none(){if state.checkpoint_action.is_none(){let request=OriginalCheckpointRequest{completed:if is_start{state.prior}else{state.next},total:state.total,owned_bytes:state.owned};checkpoint.begin(request,&mut state.checkpoint_action)?}else{let action=state.checkpoint_action.as_mut().expect("checkpoint action retained");if !checkpoint.matches_action(Some(action)){return Err(invalid())}if !action.is_settled()&&!checkpoint.recover(action)?{return Ok(None)}}let action=state.checkpoint_action.as_mut().expect("checkpoint action retained");if !action.is_settled(){return Ok(None)}state.reply=Some(Reply::Checkpoint(action.take_reply().ok_or_else(invalid)?))}checkpoint.finish(&mut state.checkpoint_action)?;let reply=match state.reply.take().ok_or_else(invalid)?{Reply::Checkpoint(reply)=>reply,_=>return Err(invalid())};match reply{Err(error)=>{ledger.finish_progress(state.identity)?;state.finished=true;drop(slot.take());return Ok(Some(Err(error)))},Ok(false)=>{ledger.finish_progress(state.identity)?;state.finished=true;drop(slot.take());return Ok(Some(Ok(false)))},Ok(true)=>{if is_start{*started=true;state.phase=Phase::Span}else{ledger.finish_progress(state.identity)?;state.finished=true;drop(slot.take());return Ok(Some(Ok(true)))}}}},
  Phase::Span=>{if state.reply.is_none(){if state.span_action.is_none(){span.begin(OriginalSpanRequest{units,owned_bytes:state.owned},&mut state.span_action)?}else{let action=state.span_action.as_mut().expect("span action retained");if !span.matches_action(Some(action)){return Err(invalid())}if !action.is_settled()&&!span.recover(action)?{return Ok(None)}}let action=state.span_action.as_mut().expect("span action retained");if !action.is_settled(){return Ok(None)}state.reply=Some(Reply::Span(action.take_reply().ok_or_else(invalid)?))}span.finish(&mut state.span_action)?;let reply=match state.reply.take().ok_or_else(invalid)?{Reply::Span(reply)=>reply,_=>return Err(invalid())};if let Err(error)=reply{ledger.finish_progress(state.identity)?;state.finished=true;drop(slot.take());return Ok(Some(Err(error)))}*completed=state.next;if state.prior/256!=state.next/256||(state.total!=0&&state.next==state.total){state.phase=Phase::End}else{ledger.finish_progress(state.identity)?;state.finished=true;drop(slot.take());return Ok(Some(Ok(true)))}}
 }}
}
#[cfg(test)]
mod tests{
 use super::*;use crate::span::{OriginalRecordedAuthority,OriginalRecordedProducer,OriginalRecordedReply,OriginalRecordedReplyComplete};use std::sync::{Arc,atomic::{AtomicUsize,Ordering}};
 struct Context<'a>{turn:&'a crate::OriginalSourceTurn,checks:AtomicUsize,panic_at:AtomicUsize}
 struct Span{turn:OriginalSourceTurnIdentity,calls:Arc<AtomicUsize>}
 impl OriginalRecordedProducer for Span{
  type Request=OriginalSpanRequest;type Reply=();type Context<'a,'b>=Context<'a> where 'b:'a;
  fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError> where 'b:'a{if c.turn.identity()!=self.turn{return Err(crate::invariant())}let count=c.checks.fetch_add(1,Ordering::Relaxed)+1;if count==c.panic_at.load(Ordering::Relaxed){panic!("original span validation interrupted")}Ok(())}
  fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity> where 'b:'a{Some(c.turn.identity())}
  fn receive<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,_:Self::Request,reply:OriginalRecordedReply<'r,()>)->Result<OriginalRecordedReplyComplete<'r,()>,ValueError> where 'b:'a{self.calls.fetch_add(1,Ordering::Relaxed);Ok(reply.complete(Ok(())))}
  fn recover<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,_:Self::Request,reply:OriginalRecordedReply<'r,()>)->Result<OriginalRecordedReplyComplete<'r,()>,ValueError> where 'b:'a{Ok(reply.pending())}
 }
 struct Check{turn:OriginalSourceTurnIdentity,calls:Arc<AtomicUsize>}
 impl OriginalRecordedProducer for Check{
  type Request=OriginalCheckpointRequest;type Reply=bool;type Context<'a,'b>=&'a crate::OriginalSourceTurn where 'b:'a;
  fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError> where 'b:'a{if c.identity()==self.turn{Ok(())}else{Err(crate::invariant())}}
  fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity> where 'b:'a{Some(c.identity())}
  fn receive<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,_:Self::Request,reply:OriginalRecordedReply<'r,bool>)->Result<OriginalRecordedReplyComplete<'r,bool>,ValueError> where 'b:'a{self.calls.fetch_add(1,Ordering::Relaxed);Ok(reply.complete(Ok(true)))}
  fn recover<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,_:Self::Request,reply:OriginalRecordedReply<'r,bool>)->Result<OriginalRecordedReplyComplete<'r,bool>,ValueError> where 'b:'a{Ok(reply.pending())}
 }
 #[test]
 fn original_ledger_blocks_a_replacement_slot_between_producer_actions(){let issuer=crate::OriginalSourceTurnIssuer::new();let turn=issuer.issue().unwrap();let span_calls=Arc::new(AtomicUsize::new(0));let check_calls=Arc::new(AtomicUsize::new(0));let mut span=OriginalRecordedAuthority::new(Span{turn:turn.identity(),calls:span_calls.clone()});let mut checkpoint=OriginalRecordedAuthority::new(Check{turn:turn.identity(),calls:check_calls.clone()});let mut sc=Context{turn:&turn,checks:AtomicUsize::new(0),panic_at:AtomicUsize::new(3)};let mut cc=&turn;let mut ledger=NativeAllocationLedger::new(0);let(mut completed,mut started)=(0,false);let(mut original,mut foreign)=(None,None);let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||span.with_send_loan(&mut sc,|span|checkpoint.with_send_loan(&mut cc,|checkpoint|advance_source_progress(turn.witness(),&mut ledger,1,&mut completed,0,&mut started,span,checkpoint,1,&mut original)).unwrap()).unwrap()));assert!(interrupted.is_err());assert!(ledger.has_progress());assert_eq!((check_calls.load(Ordering::Relaxed),span_calls.load(Ordering::Relaxed)),(1,0));sc.panic_at.store(0,Ordering::Relaxed);span.with_send_loan(&mut sc,|span|checkpoint.with_send_loan(&mut cc,|checkpoint|{assert!(advance_source_progress(turn.witness(),&mut ledger,1,&mut completed,0,&mut started,span,checkpoint,1,&mut foreign).is_err());assert!(foreign.is_none());assert!(advance_source_progress(turn.witness(),&mut ledger,1,&mut completed,0,&mut started,span,checkpoint,1,&mut original).unwrap().unwrap().unwrap())}).unwrap()).unwrap();assert!(original.is_none()&&!ledger.has_progress());assert_eq!((completed,check_calls.load(Ordering::Relaxed),span_calls.load(Ordering::Relaxed)),(1,1,1));assert!(span.into_port().is_ok());assert!(checkpoint.into_port().is_ok())}
 #[test]
 fn original_progress_preserves_checkpoint_cancellation_after_unwind(){
  struct Cancel{turn:OriginalSourceTurnIdentity,calls:Arc<AtomicUsize>}
  impl OriginalRecordedProducer for Cancel{
   type Request=OriginalCheckpointRequest;type Reply=bool;type Context<'a,'b>=&'a crate::OriginalSourceTurn where 'b:'a;
   fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError> where 'b:'a{if c.identity()==self.turn{Ok(())}else{Err(crate::invariant())}}
   fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity> where 'b:'a{Some(c.identity())}
   fn receive<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,_:Self::Request,reply:OriginalRecordedReply<'r,bool>)->Result<OriginalRecordedReplyComplete<'r,bool>,ValueError> where 'b:'a{self.calls.fetch_add(1,Ordering::Relaxed);let _done=reply.complete(Ok(false));panic!("actual cancellation interrupted")}
   fn recover<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,_:Self::Request,reply:OriginalRecordedReply<'r,bool>)->Result<OriginalRecordedReplyComplete<'r,bool>,ValueError> where 'b:'a{Ok(reply.pending())}
  }
  let issuer=crate::OriginalSourceTurnIssuer::new();let turn=issuer.issue().unwrap();let span_calls=Arc::new(AtomicUsize::new(0));let check_calls=Arc::new(AtomicUsize::new(0));let mut span=OriginalRecordedAuthority::new(Span{turn:turn.identity(),calls:span_calls.clone()});let mut checkpoint=OriginalRecordedAuthority::new(Cancel{turn:turn.identity(),calls:check_calls.clone()});let mut sc=Context{turn:&turn,checks:AtomicUsize::new(0),panic_at:AtomicUsize::new(0)};let mut cc=&turn;let mut ledger=NativeAllocationLedger::new(0);let(mut completed,mut started)=(0,false);let mut progress=None;let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||span.with_send_loan(&mut sc,|span|checkpoint.with_send_loan(&mut cc,|checkpoint|advance_source_progress(turn.witness(),&mut ledger,1,&mut completed,0,&mut started,span,checkpoint,1,&mut progress)).unwrap()).unwrap()));assert!(interrupted.is_err());assert!(ledger.has_progress());span.with_send_loan(&mut sc,|span|checkpoint.with_send_loan(&mut cc,|checkpoint|assert!(!advance_source_progress(turn.witness(),&mut ledger,1,&mut completed,0,&mut started,span,checkpoint,1,&mut progress).unwrap().unwrap().unwrap())).unwrap()).unwrap();assert!(progress.is_none()&&!ledger.has_progress());assert_eq!((completed,started,check_calls.load(Ordering::Relaxed),span_calls.load(Ordering::Relaxed)),(0,false,1,0));assert!(span.into_port().is_ok());assert!(checkpoint.into_port().is_ok());
 }
 #[test]
 fn checkpoint_only_recovers_its_actual_reply_without_a_span(){
  struct Interrupted{turn:OriginalSourceTurnIdentity,calls:Arc<AtomicUsize>}
  impl OriginalRecordedProducer for Interrupted{type Request=OriginalCheckpointRequest;type Reply=bool;type Context<'a,'b>=&'a crate::OriginalSourceTurn where 'b:'a;fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError> where 'b:'a{if c.identity()==self.turn{Ok(())}else{Err(crate::invariant())}}fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<OriginalSourceTurnIdentity> where 'b:'a{Some(c.identity())}fn receive<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,_:Self::Request,reply:OriginalRecordedReply<'r,bool>)->Result<OriginalRecordedReplyComplete<'r,bool>,ValueError> where 'b:'a{self.calls.fetch_add(1,Ordering::Relaxed);let _reply=reply.complete(Ok(true));panic!("original checkpoint after reply")}fn recover<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,_:Self::Request,reply:OriginalRecordedReply<'r,bool>)->Result<OriginalRecordedReplyComplete<'r,bool>,ValueError> where 'b:'a{Ok(reply.pending())}}
  let issuer=crate::OriginalSourceTurnIssuer::new();let turn=issuer.issue().unwrap();let calls=Arc::new(AtomicUsize::new(0));let mut owner=OriginalRecordedAuthority::new(Interrupted{turn:turn.identity(),calls:calls.clone()});let mut ledger=NativeAllocationLedger::new(7);let(mut started,mut frame,mut other)=(false,None,None);let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||owner.with_send_loan(&mut &turn,|loan|source_checkpoint(turn.witness(),&mut ledger,1,0,9,&mut started,loan,&mut frame)).unwrap().unwrap()));assert!(interrupted.is_err());assert!(ledger.has_progress());owner.with_send_loan(&mut &turn,|loan|{assert!(source_checkpoint(turn.witness(),&mut ledger,1,0,9,&mut started,loan,&mut other).is_err());assert!(source_checkpoint(turn.witness(),&mut ledger,1,0,9,&mut started,loan,&mut frame).unwrap().unwrap().unwrap())}).unwrap();assert!(started&&frame.is_none()&&!ledger.has_progress());assert_eq!(calls.load(Ordering::Relaxed),1);assert!(owner.into_port().is_ok())
 }

}
